import { shouldAttemptSilentSso, beginSilentSso, clearSilentSsoState, safeReturnTo } from '/js/silentsso.js';

const form = document.querySelector('#login-form');
const error = document.querySelector('#login-error');

// 로그인 뒤 돌아갈 자리. 401 로 여기 보내진 화면이 ?return_to= 로 넘겨 줍니다.
// 같은 출처 경로만 받습니다 — 그 외는 '/'.
const returnTo = safeReturnTo(new URLSearchParams(window.location.search).get('return_to'));

// 이미 세션이 있는지 봅니다(있으면 조용한 시도를 할 이유가 없습니다).
// 서버가 GET /login 에서 세션 쿠키를 보고 먼저 302 로 걸러 주므로 보통은 여기까지
// 오지 않지만, 그 사이 세션이 생긴 경우를 위해 남겨 둡니다.
async function hasSession() {
  try {
    const response = await fetch('/api/v1/auth/me', { headers: { Accept: 'application/json' } });
    return response.ok;
  } catch {
    return false;
  }
}

// 로그인 화면에 제품/버전 정보 표시 (공개 엔드포인트, 인증 불필요)
(async () => {
  const el = document.querySelector('#version-info');
  if (!el) return;
  try {
    const response = await fetch('/api/v1/system/info', { headers: { Accept: 'application/json' } });
    if (!response.ok) return;
    const body = await response.json();
    const product = (body.data && body.data.product) || 'DartFly';
    const version = (body.data && body.data.version) || '';
    el.textContent = version ? `${product} ${version}` : product;
    // SSO 활성화 시 버튼 표시
    if (body.data && body.data.sso_enabled) {
      const block = document.querySelector('#sso-block');
      const btn = document.querySelector('#sso-login');
      if (btn && body.data.sso_label) btn.textContent = body.data.sso_label;
      if (btn) btn.href = `/auth/sso/login?return_to=${encodeURIComponent(returnTo)}`; // 버튼으로 들어가도 그 자리로
      if (block) block.hidden = false;
    }
    // 관리자가 auto_login 을 켰으면, IdP 세션이 살아 있는 사람은 로그인 화면을
    // 거치지 않게 조용히(prompt=none) 다녀옵니다. 한 탭에 한 번만이며, 거절당해
    // ?sso=none 으로 돌아온 뒤에는 다시 시도하지 않습니다(/js/silentsso.js).
    if (shouldAttemptSilentSso(body.data)) {
      if (await hasSession()) { window.location.replace(returnTo); return; }
      beginSilentSso(returnTo);
    }
  } catch {
    /* 버전 표시는 부가 정보이므로 실패해도 무시 */
  }
})();

// SSO 콜백 실패 시 ?sso_error= 로 돌아오면 메시지를 표시합니다.
(() => {
  const err = new URLSearchParams(window.location.search).get('sso_error');
  if (err) { const el = document.querySelector('#login-error'); if (el) el.textContent = 'SSO 로그인 실패: ' + err; }
})();

form.addEventListener('submit', async (event) => {
  event.preventDefault();
  error.textContent = '';
  const button = form.querySelector('button');
  button.disabled = true;
