// 브라우저용 모듈을 Node 에서 불러오는 공용 로더.
//
// 화면 모듈은 '/js/foo.js' 처럼 브라우저 절대 경로로 서로를 참조합니다. Node 는 그
// 경로를 해석하지 못하므로 파일 URL 로 바꿔 읽습니다. 모듈이 서로를 참조하기
// 시작하면 테스트마다 같은 처리를 하게 되므로 한 곳에 둡니다.
import { readFileSync } from 'node:fs';

const REPO = new URL('../../', import.meta.url);
const ROOT = new URL('internal/webui/js/', REPO);

// repoFile: 저장소 기준 경로를 현재 작업 디렉터리와 무관하게 읽습니다.
//
// 예전에는 테스트들이 readFileSync('internal/webui/js/app.js') 처럼 상대 경로를
// 썼습니다. 저장소 최상위에서 실행할 때만 통했고, 다른 곳에서 부르면 ENOENT 로
// 죽었습니다.
export function repoFile(path) {
  return readFileSync(new URL(path, REPO), 'utf8');
}

export async function loadModule(name) {
  const source = readFileSync(new URL(name, ROOT), 'utf8')
    .replaceAll(/from '\/js\/([\w.-]+)'/g, (_, dep) => `from '${new URL(dep, ROOT).href}'`);
  return import('data:text/javascript;base64,' + Buffer.from(source).toString('base64'));
}
package server

import (
	"net/http"
	"strconv"

	"github.com/hkjang/dartfly/internal/query"
)

func resultsaveSession(w http.ResponseWriter, r *http.Request, options Options) (int64, bool, bool) {
	session, ok := authenticatedSession(r, options)
	if !ok {
		writeProblem(w, r, http.StatusUnauthorized, "DF_AUTH_REQUIRED", "로그인이 필요합니다")
		return 0, false, false
	}
	if options.ResultSave == nil {
		writeProblem(w, r, http.StatusServiceUnavailable, "DF_SYSTEM_MASTER_KEY_UNAVAILABLE", "결과 저장 서비스가 구성되지 않았습니다(Master Key 필요)")
		return 0, false, false
	}
	return session.User.Seq, isManager(session.User.Role), true
}

func saveResultHandler(options Options) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		userID, admin, ok := resultsaveSession(w, r, options)
		if !ok {
			return
		}
		var input struct {
			DBSeq      int64          `json:"db_seq"`
			SQL        string         `json:"sql"`
			Parameters map[string]any `json:"parameters"`
			MaxRows    int            `json:"max_rows"`
		}
		if err := decodeJSON(w, r, &input); err != nil || input.DBSeq <= 0 {
			writeProblem(w, r, http.StatusBadRequest, "DF_SQL_INVALID_REQUEST", "결과 저장 요청 형식이 올바르지 않습니다")
			return
		}
		maxRows := input.MaxRows
		if maxRows <= 0 || maxRows > options.MaxRows {
			maxRows = options.MaxRows
		}
		ids := requestIDsFrom(r.Context())
		saved, err := options.ResultSave.Save(r.Context(), input.DBSeq, userID, admin, input.SQL, query.Options{
			MaxRows: maxRows, Timeout: options.QueryTimeout, AuditID: ids.AuditID, TraceID: ids.TraceID,
			ActorID: strconv.FormatInt(userID, 10), ClientIP: clientIP(r), ServerBind: true, NamedParams: input.Parameters,
		})
		if err != nil {
			writeExecutionProblem(w, r, err)
			return
		}
		writeSuccessStatus(w, r, http.StatusCreated, saved)
	}
}

func listSavedResultsHandler(options Options) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		userID, admin, ok := resultsaveSession(w, r, options)
		if !ok {
			return
		}
		limit, offset := 100, 0
		if v := r.URL.Query().Get("limit"); v != "" {
			if p, err := strconv.Atoi(v); err == nil {
				limit = p
			}
		}
		if v := r.URL.Query().Get("offset"); v != "" {
			if p, err := strconv.Atoi(v); err == nil {
				offset = p
			}
		}
		page, err := options.ResultSave.List(r.Context(), userID, admin, limit, offset)
		if err != nil {
			writeProblem(w, r, http.StatusInternalServerError, "DF_SAVE_LIST_FAILED", "저장된 결과를 조회할 수 없습니다")
			return
		}
		writeSuccess(w, r, page)
	}
}

func getSavedResultHandler(options Options) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		userID, admin, ok := resultsaveSession(w, r, options)
		if !ok {
			return
		}
		id, err := strconv.ParseInt(r.PathValue("id"), 10, 64)
		if err != nil {
			writeProblem(w, r, http.StatusBadRequest, "DF_SAVE_INVALID_REQUEST", "결과 ID가 올바르지 않습니다")
			return
		}
		detail, err := options.ResultSave.Get(r.Context(), id, userID, admin)
		if err != nil {
			writeProblem(w, r, http.StatusNotFound, "DF_SAVE_NOT_FOUND", err.Error())
			return
		}
		writeSuccess(w, r, detail)
	}
}

func deleteSavedResultHandler(options Options) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		userID, admin, ok := resultsaveSession(w, r, options)
		if !ok {
			return
