export async function api(path, options = {}) {
  const headers = { Accept: 'application/json', ...(options.headers || {}) };
  if (options.method && options.method !== 'GET') headers['X-DartFly-CSRF'] = csrfToken;
  const response = await fetch(path, { ...options, headers });
  if (response.status === 401) { window.location.replace(loginUrl()); throw new Error('로그인이 필요합니다.'); }
  const body = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(body.title || body.detail || '요청을 처리하지 못했습니다.');
  return body.data;
}

